const $=s=>document.querySelector(s),grid=$('#custom-grid'),built=$('#built-grid'),summary=$('#grid-summary'),help=$('#grid-help'),status=$('#build-status');let mode='spaces',running=false,attempts=0,pattern,highlights=new Set(),worker=null,buildStart=0,progressTimer=null,progressPhase='',filled=0;
for (const [label, href] of [['Verify', '../verify/index.html'], ['Techniques', '../techniques/index.html']]) { const link = document.createElement('a'); link.textContent = label; link.href = href; document.querySelector('.nav-menu > div').append(link); }
const shuffle=a=>{a=[...a];for(let i=a.length-1;i;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a},box=(r,c)=>Math.floor(r/3)*3+Math.floor(c/3),key=(r,c)=>r*9+c;
function freshPattern(){const p=Array.from({length:9},()=>Array(9).fill(false));for(let band=0;band<3;band++){const o=[shuffle([0,1,2]),shuffle([0,1,2]),shuffle([0,1,2])],rows=shuffle([0,1,2]),perms=shuffle([[0,1,2],[1,2,0],[2,0,1]]);for(let local=0;local<3;local++)for(let st=0;st<3;st++)p[band*3+local][st*3+o[st][perms[rows[local]][st]]]=true}return p}
function validPattern(){return pattern.every(r=>r.filter(Boolean).length===3)&&[0,1,2,3,4,5,6,7,8].every(c=>pattern.map(r=>r[c]).filter(Boolean).length===3)&&[0,1,2].every(br=>[0,1,2].every(bc=>pattern.slice(br*3,br*3+3).flatMap(r=>r.slice(bc*3,bc*3+3)).filter(Boolean).length===3))}
function counts(r,c){return[pattern[r].filter(Boolean).length,pattern.map(x=>x[c]).filter(Boolean).length,pattern.slice(Math.floor(r/3)*3,Math.floor(r/3)*3+3).flatMap(x=>x.slice(Math.floor(c/3)*3,Math.floor(c/3)*3+3)).filter(Boolean).length]}
function render(){grid.replaceChildren();let spaces=0;for(let r=0;r<9;r++)for(let c=0;c<9;c++){let shaded=pattern[r][c],cell=document.createElement('button');if(shaded)spaces++;cell.type='button';cell.disabled=running;cell.className=`cell custom-cell${shaded?' shaded':''}${highlights.has(key(r,c))?' highlighted':''}${c%3===2?' box-right':''}${r%3===2?' box-bottom':''}`;cell.setAttribute('aria-label',`Row ${r+1}, column ${c+1}`);cell.onclick=()=>click(r,c);grid.append(cell)}summary.textContent=`${spaces} spaces · ${highlights.size} clues`;$('#build-now').disabled=running||!validPattern()||!highlights.size;}
function click(r,c){if(running)return;if(mode==='spaces'){if(pattern[r][c]){pattern[r][c]=false;highlights.delete(key(r,c))}else if(counts(r,c).every(n=>n<3))pattern[r][c]=true;else{status.textContent='That space would make a row, column, or box exceed three grey cells.';return}}else if(!pattern[r][c]){let k=key(r,c);highlights.has(k)?highlights.delete(k):highlights.add(k)}render()}
let resultVersion=0;
function showResult(givens,solution,rating){const version=++resultVersion,resultPattern=pattern.map(row=>[...row]);built.replaceChildren();for(let r=0;r<9;r++)for(let c=0;c<9;c++){let x=document.createElement('div'),d=givens[r][c];x.className=`cell${resultPattern[r][c]?' shaded':''}${!resultPattern[r][c]&&!d?' empty':''}${c%3===2?' box-right':''}${r%3===2?' box-bottom':''}`;if(d)x.textContent=d;built.append(x)}let copy=$('#copy-built-dynamic');if(!copy){copy=document.createElement('button');copy.id='copy-built-dynamic';copy.className='copy-button';copy.textContent='Copy 162-string';$('#built-result').insertBefore(copy,$('#custom-walkthrough'))}copy.onclick=async()=>{const code=resultPattern.flat().map(x=>x?'1':'0').join('')+givens.flat().map(x=>x??'0').join('');await navigator.clipboard.writeText(code);status.textContent='Built puzzle copied as a 162-character ExtraSudokuSpace string.'};let score=$('#built-rating');if(!score){score=document.createElement('p');score.id='built-rating';score.className='selected-cells';$('#built-result').insertBefore(score,$('#custom-walkthrough'))}score.textContent=`Difficulty score: ${rating.score.toLocaleString()}${rating.backtrackingSteps?` (${rating.backtrackingSteps} backtracking ${rating.backtrackingSteps===1?'step':'steps'})`:''}`;const walkthrough=$('#custom-walkthrough');walkthrough.textContent='Preparing solution walkthrough…';$('#built-result').hidden=false;$('#attempt-count').textContent=`${attempts} attempts`;import('../walkthrough.js').then(({mountWalkthrough})=>{if(version!==resultVersion||$('#built-result').hidden)return;mountWalkthrough(walkthrough,{pattern:resultPattern,dug:givens,values:solution})}).catch(error=>{if(version===resultVersion&&!$('#built-result').hidden)walkthrough.textContent=`Walkthrough unavailable: ${error.message}`})}
function updateProgress(){status.textContent=`${progressPhase}… ${attempts.toLocaleString()} fill attempts · ${filled.toLocaleString()} completed grids · ${((performance.now()-buildStart)/1000).toFixed(1)} s`}
function stopWorker(){if(worker){worker.terminate();worker=null}clearInterval(progressTimer);progressTimer=null;running=false;$('#halt-build').disabled=true;for(const id of ['#space-mode','#clue-mode','#new-pattern','#clear-highlights','#difficulty-min','#difficulty-max'])$(id).disabled=false;render()}
$('#space-mode').onclick=()=>{mode='spaces';$('#space-mode').classList.add('active');$('#clue-mode').classList.remove('active');help.textContent='Space mode: click cells to set the 27 grey spaces. A row, column, or box cannot exceed three spaces.'};$('#clue-mode').onclick=()=>{mode='clues';$('#clue-mode').classList.add('active');$('#space-mode').classList.remove('active');help.textContent='Clue mode: click any white cell to highlight it green. These become the givens.'};$('#new-pattern').onclick=()=>{pattern=freshPattern();highlights.clear();render();status.textContent='New valid 27-space pattern created.'};$('#clear-highlights').onclick=()=>{highlights.clear();render()};
$('#build-now').onclick=()=>{
  if(running||!validPattern()||!highlights.size)return;
  const minDifficulty=Number($('#difficulty-min').value),maxDifficulty=Number($('#difficulty-max').value);
  if(minDifficulty>maxDifficulty){status.textContent='Minimum difficulty must not exceed maximum difficulty.';return}
  running=true;attempts=0;filled=0;buildStart=performance.now();progressPhase='Starting search';
  resultVersion++;$('#halt-build').disabled=false;$('#built-result').hidden=true;
  for(const id of ['#space-mode','#clue-mode','#new-pattern','#clear-highlights','#difficulty-min','#difficulty-max'])$(id).disabled=true;
  render();updateProgress();
  try {
    const active=new Worker('./build-worker.js',{type:'module'});worker=active;
    active.onmessage=({data})=>{
      if(worker!==active)return;
      attempts=data.attempts;filled=data.filled;
      if(data.type==='progress'){progressPhase=data.phase;updateProgress();return}
      const seconds=((performance.now()-buildStart)/1000).toFixed(1);
      stopWorker();
      if(data.type==='success'){showResult(data.givens,data.values,data.rating);status.textContent=`Unique puzzle found after ${attempts.toLocaleString()} fill attempts in ${seconds} s.`}
      else if(data.type==='impossible')status.textContent=`This grey pattern has no valid completed grid (proved after ${attempts.toLocaleString()} fill attempts). Change the grey pattern and try again.`;
      else status.textContent=`Build failed: ${data.message}`;
    };
    active.onerror=()=>{if(worker!==active)return;stopWorker();status.textContent='Could not run the build worker. Serve this site over HTTP and try again.'};
    progressTimer=setInterval(updateProgress,250);
    active.postMessage({pattern:pattern.map(row=>[...row]),highlights:[...highlights],minDifficulty,maxDifficulty});
  } catch(error){stopWorker();status.textContent=`Could not start the build: ${error.message}`}
};
$('#halt-build').onclick=()=>{if(!running)return;const seconds=((performance.now()-buildStart)/1000).toFixed(1);stopWorker();status.textContent=`Stopped after ${attempts.toLocaleString()} fill attempts and ${seconds} s. Your selections are unchanged.`};pattern=freshPattern();render();
